from typing import Any


def with_acceptance_source_refs(units: list[dict[str, Any]]) -> list[dict[str, Any]]:
    for unit in units:
        unit_id = str(unit.get("unit_id", "")).strip()
        for criterion in unit.get("acceptance_criteria", []):
            if not isinstance(criterion, dict):
                continue
            ac_id = str(criterion.get("ac_id", "")).strip()
            criterion.setdefault(
                "source_refs",
                [
                    "brief.json#acceptance_criteria[0]",
                    "phase-1/phase-prd.json#coverage_matrix",
                    f"phase-1/units/{unit_id}.json#acceptance_criteria:{ac_id}",
                ],
            )
    return units


